<?php
namespace App\Http\Controllers;use App\Models\{Employee,EmployeeTrip};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class TripController extends Controller{public function index(Request $r){$q=EmployeeTrip::with('employee')->latest('start_date');$q->when($r->search,fn($q,$v)=>$q->where(fn($x)=>$x->where('destination','like',"%$v%")->orWhere('purpose','like',"%$v%")->orWhereHas('employee',fn($e)=>$e->where('name','like',"%$v%"))))->when($r->employee_id,fn($q,$v)=>$q->where('employee_id',$v))->when($r->from,fn($q,$v)=>$q->whereDate('start_date','>=',$v))->when($r->to,fn($q,$v)=>$q->whereDate('end_date','<=',$v))->when($r->status&&$r->status!=='All',fn($q)=>$q->where('status',$r->status));$counts=['All'=>EmployeeTrip::count(),'Planned'=>EmployeeTrip::whereStatus('Planned')->count(),'Ongoing'=>EmployeeTrip::whereStatus('Ongoing')->count(),'Completed'=>EmployeeTrip::whereStatus('Completed')->count(),'Cancelled'=>EmployeeTrip::whereStatus('Cancelled')->count()];return view('trips.index',['trips'=>$q->paginate(10)->withQueryString(),'employees'=>Employee::orderBy('name')->get(),'counts'=>$counts]);}public function store(Request $r){$this->save($r,new EmployeeTrip);return back()->with('success','Trip created successfully.');}public function update(Request $r,EmployeeTrip $trip){$this->save($r,$trip);return back()->with('success','Trip updated successfully.');}public function status(Request $r,EmployeeTrip $trip){$trip->update($r->validate(['status'=>'required|in:Planned,Ongoing,Completed,Cancelled']));return back()->with('success','Trip status updated.');}public function finance(Request $r,EmployeeTrip $trip){$trip->update($r->validate(['advance_amount'=>'nullable|numeric|min:0','advance_status'=>'nullable|in:Requested,Approved,Paid,Reconciled','expense_amount'=>'nullable|numeric|min:0','expense_status'=>'nullable|in:Pending,Approved,Paid,Rejected']));return back()->with('success','Trip finance updated.');}public function document(EmployeeTrip $trip){abort_unless($trip->document_path&&Storage::disk('public')->exists($trip->document_path),404);return Storage::disk('public')->response($trip->document_path);}public function destroy(EmployeeTrip $trip){if($trip->document_path)Storage::disk('public')->delete($trip->document_path);$trip->delete();return back()->with('success','Trip deleted.');}private function save(Request $r,EmployeeTrip $trip):void{$d=$r->validate(['employee_id'=>'required|exists:employees,id','purpose'=>'required|string|max:191','destination'=>'required|string|max:191','start_date'=>'required|date','end_date'=>'required|date|after_or_equal:start_date','description'=>'nullable|string|max:3000','expected_outcomes'=>'nullable|string|max:3000','document'=>'nullable|file|mimes:pdf,jpg,jpeg,png,doc,docx|max:5120','advance_amount'=>'nullable|numeric|min:0']);unset($d['document']);if($r->hasFile('document')){if($trip->document_path)Storage::disk('public')->delete($trip->document_path);$d['document_path']=$r->file('document')->store('trips','public');}if(isset($d['advance_amount'])&&!$trip->exists)$d['advance_status']='Requested';$trip->fill($d)->save();}}
